{
  "candidate_edge_types": [
    {
      "name": "DIAGNOSES_CAUSE_OF_FAILURE",
      "definition": "Agent reasoning that inspects an earlier failed or blocked execution to identify the underlying cause or missing prerequisite.",
      "source_description": "An earlier execution failure or blocked verification step observed in the trajectory.",
      "target_description": "Agent diagnostic reasoning that identifies the cause of the failure."
    },
    {
      "name": "ATTEMPTS_TO_REPAIR_BLOCKER",
      "definition": "A subsequent agent action modifies the execution environment to resolve a previously identified failure cause or missing prerequisite.",
      "source_description": "A diagnosed failure cause or missing prerequisite of an earlier execution failure.",
      "target_description": "An agent action that creates or restores the missing prerequisite and thereby attempts to remove the blocker."
    },
    {
      "name": "REEXECUTES_VERIFICATION_AFTER_REMEDIATION",
      "definition": "After attempting to resolve the cause of an earlier failed verification, the agent re-executes that verification to determine whether the remediation succeeded.",
      "source_description": "An earlier verification or test execution that failed because of a missing prerequisite or other blocker.",
      "target_description": "A subsequent execution of the same verification after the agent has attempted to resolve the blocker."
    },
    {
      "name": "INITIATES_TASK_COMPLETION_FOLLOWING_SUCCESSFUL_VERIFICATION",
      "definition": "After observing a successful verification result, the agent decides that the task is complete and invokes a task-completion action.",
      "source_description": "A successful verification or test result observed during execution.",
      "target_description": "An agent task-completion action or completion request."
    },
    {
      "name": "CONFIRMS_TASK_COMPLETION_IN_RESPONSE_TO_CONFIRMATION_PROMPT",
      "definition": "After a task-completion action elicits a confirmation prompt, the agent re-issues the completion action to confirm task completion.",
      "source_description": "A confirmation prompt or request generated in response to an earlier task-completion action.",
      "target_description": "A repeated task-completion action or confirmation submitted by the agent."
    }
  ]
}

